package com.jobsphere.controller;
import com.jobsphere.entity.*;import com.jobsphere.repository.*;import com.jobsphere.service.*;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/dashboard") public class DashboardController extends BaseController {final UserProfileRepository profiles;final DashboardInsightRepository insights;final CareerAnalysisRepository careers;final ResumeAnalysisRepository resumes;public DashboardController(TokenService t,UserRepository u,UserProfileRepository p,DashboardInsightRepository i,CareerAnalysisRepository c,ResumeAnalysisRepository r){super(t,u);profiles=p;insights=i;careers=c;resumes=r;}
 @GetMapping public Map<String,Object> dashboard(@RequestHeader("Authorization") String h){User u=currentUser(h);Optional<UserProfile> p=profiles.findByUserId(u.id);if(p.isEmpty())return Map.of("hasProfile",false,"user",Map.of("fullName",u.fullName,"email",u.email),"message","Complete your profile to unlock your personalized JOBSPHERE dashboard.");DashboardInsight d=insights.findAll().stream().filter(x->u.id.equals(x.userId)).max(Comparator.comparing(x->x.createdAt)).orElse(null);CareerAnalysis c=careers.findAll().stream().filter(x->u.id.equals(x.userId)).max(Comparator.comparing(x->x.createdAt)).orElse(null);ResumeAnalysis r=resumes.findAll().stream().filter(x->u.id.equals(x.userId)).max(Comparator.comparing(x->x.createdAt)).orElse(null);Map<String,Object> out=new LinkedHashMap<>();out.put("hasProfile",true);out.put("user",Map.of("fullName",u.fullName,"email",u.email));out.put("profile",p.get());out.put("dashboardInsight",d==null?null:d.insightJson);out.put("latestCareerAnalysis",c==null?null:c.analysisJson);out.put("latestResumeAnalysis",r==null?null:r.analysisJson);return out;}
}
